<?php
if(!admin()){echo '<p>Acesso restrito a administradores.</p>';return;}
if($_SERVER['REQUEST_METHOD']==='POST'){
try{verify_csrf();$nome=trim($_POST['nome']??'');$email=trim($_POST['email']??'');$senha=$_POST['senha']??'';$tipo=in_array($_POST['tipo']??'', ['usuario','administrador'],true)?$_POST['tipo']:'usuario';if(!$nome||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($senha)<12)throw new RuntimeException('Informe nome, e-mail e senha de pelo menos 12 caracteres.');$hash=password_hash($senha,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO usuarios(nome,email,senha,tipo) VALUES(?,?,?,?)');$s->bind_param('ssss',$nome,$email,$hash,$tipo);$s->execute();flash('Usuário cadastrado.');}catch(Throwable $e){flash('Erro: '.$e->getMessage());}go('usuarios');}
$rows=$conn->query('SELECT nome,email,tipo,ativo FROM usuarios ORDER BY nome');
?><h1>Usuários</h1><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Nome<input name="nome" required></label><label>E-mail<input name="email" type="email" required></label><label>Senha<input name="senha" type="password" minlength="12" required></label><label>Perfil<select name="tipo"><option value="usuario">Usuário</option><option value="administrador">Administrador</option></select></label><button>Cadastrar usuário</button></form><table><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Ativo</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=h($r['nome'])?></td><td><?=h($r['email'])?></td><td><?=h($r['tipo'])?></td><td><?=$r['ativo']?'Sim':'Não'?></td></tr><?php endwhile;?></table>
